select c.credit_limit, t.pct_returned, t.total_discount from customers c left outer join (select customer_id, round((100 * sum(case when status = 'RETURNED' then 1 else 0 end)) / count(*), 1) as pct_returned, sum(discount) as total_discount from orders where shipping_fee >= 11 group by customer_id) t on c.id = t.customer_id where t.pct_returned > 47 order by credit_limit desc, total_discount
